<script setup>import { ChevronLeft, ChevronRight } from 'lucide-vue-next'; defineProps({ page: Number, total: Number, pageSize: { type: Number, default: 10 } }); defineEmits(['update:page'])</script>
<template><div class="pagination"><span>Mostrando {{ Math.min((page - 1) * pageSize + 1, total) }}–{{ Math.min(page * pageSize, total) }} de {{ total }}</span><div><button :disabled="page <= 1" @click="$emit('update:page', page - 1)"><ChevronLeft :size="16" /></button><span>Página {{ page }} de {{ Math.max(1, Math.ceil(total / pageSize)) }}</span><button :disabled="page >= Math.ceil(total / pageSize)" @click="$emit('update:page', page + 1)"><ChevronRight :size="16" /></button></div></div></template>
